// Filename: AsteroidSprite.js
// Kitty Vs Everything — v3.22.0
// Sprite pipeline for the destructible asteroid (AsteroidBonus.js): the
// pixel-art asteroid from `.assets/Asteroid pixel_art_small.png` (241x217,
// transparent background).
//
// The PNG is embedded below as base64 (generated from the file) so the sprite
// works in BOTH the dev server (native ES modules) and the single-file
// standalone build (runs from a double-click — no server, no .assets folder
// next to it).
//
// Pipeline (runs once, at import time — long before the first asteroid spawns):
//   1. Tight-crop the transparent margins (bounding box of opaque pixels).
//   2. Downscale to a 128-px-wide game sprite (bilinear, aspect preserved).
//   3. Generate jagged shard sub-sprites — the rock clipped to seeded
//      irregular polygons. These are the "fragment parts" used by the
//      multi-tier destruction: a Large asteroid shatters into Medium + Small
//      shards, each drawn from a different jagged chunk so the pieces read as
//      broken jagged rocks (jagged balls / shards), not clean pie-slice cuts.
export const VERSION = 'v3.22.0';

const PNG_BASE64 = '';

const TARGET_W = 128; // full-sprite width (px); a Large asteroid draws at 92px
const TAU = Math.PI * 2;
const SHARD_COUNT = 8; // distinct jagged shard shapes for the fragments

let spriteCanvas = null; // full asteroid sprite (HTMLCanvasElement)
let shards = null;       // [SHARD_COUNT] jagged shard sub-sprites — the fragments
let loadPromise = null;

function buildSprite(img) {
  const W = img.naturalWidth;
  const H = img.naturalHeight;

  // 1) Draw at natural size, then tight-crop the transparent margins.
  const src = document.createElement('canvas');
  src.width = W;
  src.height = H;
  const sctx = src.getContext('2d', { willReadFrequently: true });
  sctx.drawImage(img, 0, 0);
  const id = sctx.getImageData(0, 0, W, H);
  const px = id.data;
  let minX = W, minY = H, maxX = -1, maxY = -1;
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      if (px[(y * W + x) * 4 + 3] > 8) { // ignore near-transparent noise
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  if (maxX < 0) throw new Error('Asteroid sprite: no opaque pixels found');
  const cw = maxX - minX + 1;
  const ch = maxY - minY + 1;

  // 2) Downscale the cropped rock to the game sprite size (aspect preserved).
  const outH = Math.max(1, Math.round(TARGET_W * (ch / cw)));
  const out = document.createElement('canvas');
  out.width = TARGET_W;
  out.height = outH;
  const octx = out.getContext('2d', { willReadFrequently: true });
  octx.imageSmoothingEnabled = true;
  octx.imageSmoothingQuality = 'high';
  octx.drawImage(src, minX, minY, cw, ch, 0, 0, TARGET_W, outH);

  // 3) Generate jagged shard sub-sprites: the rock clipped to seeded
  //    irregular polygons. Each fragment (Medium / Small) is drawn from one
  //    jagged chunk, so the pieces read as broken jagged rocks (jagged balls
  //    / shards) rather than clean pie-slice quarters.
  const q = [];
  for (let i = 0; i < SHARD_COUNT; i++) {
    q.push(makeJaggedShard(out, 1013 + i * 97));
  }
  return { full: out, shards: q };
}

/**
 * Clip the full rock to a seeded jagged irregular polygon → a broken chunk.
 * @param {HTMLCanvasElement} full The full rock sprite.
 * @param {number} seed Deterministic seed for the jagged outline.
 * @returns {HTMLCanvasElement} A jagged shard sub-sprite.
 */
function makeJaggedShard(full, seed) {
  const W = full.width, H = full.height;
  const c = document.createElement('canvas');
  c.width = W;
  c.height = H;
  const ctx = c.getContext('2d');
  const rnd = mulberry32(seed);
  const cx = W / 2, cy = H / 2;
  const baseR = Math.min(W, H) * 0.5;
  const K = 10 + Math.floor(rnd() * 3); // 10-12 vertices
  const startA = rnd() * TAU;
  ctx.beginPath();
  for (let i = 0; i <= K; i++) {
    const idx = i % K;
    const a = startA + (idx / K) * TAU + (rnd() - 0.5) * 0.3; // angular jitter
    const r = baseR * (0.7 + 0.42 * rnd()); // jagged radius (broken edges)
    const px = cx + Math.cos(a) * r;
    const py = cy + Math.sin(a) * r;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.clip();
  ctx.drawImage(full, 0, 0);
  return c;
}

/** Deterministic 32-bit PRNG (mulberry32) — stable jagged shapes per seed. */
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** @returns {HTMLCanvasElement|null} Full asteroid sprite, or null before ready. */
export function getAsteroidSprite() {
  return spriteCanvas;
}

/** @returns {HTMLCanvasElement[]|null} 4 quadrant shard sub-sprites, or null. */
export function getAsteroidShards() {
  return shards;
}

/** @returns {boolean} True once the sprite pipeline has finished. */
export function isAsteroidSpriteReady() {
  return spriteCanvas !== null;
}

/**
 * Kick off (or join) the sprite pipeline.
 * @returns {Promise<void>} Resolves when the sprite is ready.
 */
export function loadAsteroidSprite() {
  if (!loadPromise) {
    loadPromise = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => {
        try {
          const { full, shards: s } = buildSprite(img);
          spriteCanvas = full;
          shards = s;
          resolve();
        } catch (err) {
          loadPromise = null; // allow a retry
          reject(err);
        }
      };
      img.onerror = () => {
        loadPromise = null;
        reject(new Error('Asteroid sprite: failed to decode embedded PNG'));
      };
      img.src = 'data:image/png;base64,' + PNG_BASE64;
    });
  }
  return loadPromise;
}

// Start at import time: an asteroid can spawn any time (internet bonus / dev
// panel), so the sprite is ready well before it's needed. Failures are
// non-fatal — AsteroidBonus falls back to the procedural rock until (if) the
// pipeline succeeds.
loadAsteroidSprite().catch(() => {});
